-- Adds a per-meal breakdown (Meal A/B/C...) to each of the 48 Lazy
-- Lifter day-plans imported by supabase_lazylifter_prep_meals_import.sql.
--
-- Methodology: each meal's macros are the plan's own already-stored day
-- totals (calories/protein/carbs/fat_per_100g, themselves copied verbatim
-- from each PDF's MEAL PLAN TOTAL) split proportionally by that meal's
-- estimated relative calorie size. The per-meal split is an ESTIMATE
-- based on standard reference kcal for the foods listed (rice, chicken,
-- eggs, tuna, etc.) -- it is not independently measured -- but the four
-- meals in a plan always sum back exactly to that plan's own day total,
-- so it never contradicts the totals already shown elsewhere in the app.
-- Fiber/sodium aren't in the source PDFs at the day level either, so they
-- stay 0 per meal too, same as the day-level rows.
--
-- Run this AFTER supabase_lazylifter_prep_meals_import.sql and after
-- supabase_prep_meals_no_cook_category_migration.sql (which adds the
-- meal_breakdown column).

update prep_meals set meal_breakdown = '[{"label":"Meal A","ingredients":"Rolled Oats (Quaker) 1/2 cup, Low Fat Milk 1/2 cup, Sugar 1 tsp, Black Coffee 1 cup","calories":139,"protein":11.9,"carbs":15.2,"fat":3.3,"fiber":0,"sodium":0},{"label":"Meal B","ingredients":"Chicken Breast 80g, Baguio Beans 1/2 cup, Baby Potatoes 1/2 cup, Dari Cream Butter 1/2 tbsp, Rice 1/2 cup","calories":388,"protein":33.3,"carbs":42.3,"fat":9.3,"fiber":0,"sodium":0},{"label":"Meal C","ingredients":"Black Forest Bread (Gardenia) 2 slices, Peanut Butter (Lady''s Choice) 1 tbsp, Whey Protein 1 scoop","calories":394,"protein":33.8,"carbs":43,"fat":9.5,"fiber":0,"sodium":0},{"label":"Meal D","ingredients":"Century Tuna Chunks in Oil 1/2 can, Cabbage 1 cup, Rice 1/2 cup","calories":279,"protein":23.9,"carbs":30.4,"fat":6.7,"fiber":0,"sodium":0}]'::jsonb where name = 'Easy Cook — 1200 kcal (Plan 1)';
